// VIOC_contemporary.sqf - agregado por tools/vio_build.py, parche "contemporary_assets" (copia configurada, no es del
// autor de la mision). Politica V6.1 de equipo contemporaneo (aprox. 1990-2026) para los VEHICULOS de la mision:
//  - fuera los de la 2.a Guerra Mundial (T-34/T-34-85, C-47/AC-47, Li-2) y los futuristas del universo vanilla 2035
//    (Blackfish, Xi'an, Ghost Hawk, Blackfoot, Kajman, Taru, Shikra, Black Wasp, Varsuk, Angara, Marshall, Qilin...);
//  - por defecto, fuera tambien lo que agrega la pasada automatica de los Creator DLC WS/RF/EF de units_extra_dlc
//    (universo 2035; UNA, ION, Tura, SFIA, MJTF: no son ni EE.UU. ni Rusia), salvo lo que se ponga en VIOC_CA_ALLOW;
//  - se aplica a todo lo que la mision genera con sus listas: menus de compra de todas las fabricas (jugador, IA y lo
//    que lea esas listas: bases avanzadas, aerodromos), plantillas de escuadra de la IA (con sus niveles T0..Tn y
//    "All"), guarniciones de pueblo (Oeste, Este y guerrilla), vehiculos iniciales, defensas de la base y plantilla
//    de defensas del comandante IA, defensas de pueblo (solo servidor), menu de artilleria y partidas guardadas
//    (Server_LoadFromProfile.sqf). La infanteria no se toca.
//  - pedido del usuario (2026-10-16): fuera el M60A3 (todas sus variantes) y, en su lugar, un M1A1 Abrams de la nacion
//    principal y el camuflaje del escenario, al MISMO nivel de mejora que tenia el M60A3 (fabricas, escuadras IA y pueblos);
//  - nunca pone un vehiculo de 2035 ni de la 2.a GM en lugar de otro: si no hay un reemplazo contemporaneo verificado
//    (VIOC_CA_REPLACE, VIOC_CA_DEF_REPLACE), la opcion se quita y queda anotada en VIOC_CA_MISSING.
// Init_Common.sqf lo compila una vez en cada maquina, antes de Techmatrix.sqf (define las listas y VIOC_CA_fnc_banned,
// que VIOC_units_dlc.sqf usa para no agregar, ni gastar su cupo de 40 vehiculos de los Creator DLC, en lo prohibido);
// luego llama VIOC_CA_fnc_filterAll justo antes de pylons.sqf, cuando ya estan todas las fabricas, escuadras, pueblos,
// defensas y los parches units_extra_qav y units_extra_dlc, y antes de que nada las use.
// Parametro de lobby VIOC_CONTEMPORARY_ASSETS: 0 = no (todo como antes); 1 = si (por defecto, tambien en "Un jugador",
// donde la mision no lee el lobby); 2 = estricto (ademas Hunter, Ifrit, Prowler, Orca, MH-9/AH-9, Tempest, drones
// Greyhawk/Ababil, SAM/radar vanilla y la AAF/LDF de VIOC_DLC_VEHICLES = 2); 3 = como 1, pero conserva los vehiculos de
// WS/RF/EF que pasen las reglas A-C.
// Reglas (verificadas offline contra la configuracion de la linea de mods de Tanoa; ver REPORT.txt):
//  A) hereda de una base "segura" (VIOC_CA_SAFE: solo tiene descendientes vanilla, del mod QAV o de la 2.a GM) -> fuera;
//  B) el nombre empieza por B_/O_/I_/C_/EF_ y hereda de una base "compartida" (VIOC_CA_SHARED) -> fuera. Sin el prefijo
//     NO se quita: el UH-60M, AH-64D, AH-1Z, Mi-24, Mi-8, Su-25, A-10, M1, M109, M2 Bradley, BMP, ZSU-23-4, Tigr,
//     Kamaz y casi todos los HMMWV/M-ATV de RHS y CUP heredan de esas bases vanilla;
//  C) clase exacta (VIOC_CA_EXACT);
//  D) modos 1 y 2: vehiculo de un Creator DLC WS/RF/EF (misma prueba que usa VIOC_units_dlc.sqf para su lista).
//  VIOC_CA_ALLOW (lista blanca, en minusculas) gana a todas.
// Consola (LOCAL EXEC): VIOC_CA_REMOVED (clases quitadas), VIOC_CA_REMOVED_AT ([lista, clase]), VIOC_CA_REPLACED
// ([lista, antes, ahora]), VIOC_CA_MISSING ([lista, motivo]); ["clase"] call VIOC_CA_fnc_banned -> true/false.

VIOC_CA_MODE = missionNamespace getVariable ["VIOC_CONTEMPORARY_ASSETS", 1];
if !(VIOC_CA_MODE isEqualType 0) then {VIOC_CA_MODE = 1};
VIOC_CA_REMOVED = [];
VIOC_CA_REMOVED_AT = [];
VIOC_CA_REPLACED = [];
VIOC_CA_MISSING = [];
VIOC_CA_CACHE = createHashMap;

//--- A) bases seguras. Modo 1 y 3: diseno ficticio de 2035 o duplicado y la 2.a GM de CUP. Modo 2 agrega VIOC_CA_SAFE2.
VIOC_CA_SAFE1 = ["Heli_Transport_04_base_F", "VTOL_Base_F", "Plane_Fighter_01_Base_F", "Plane_Fighter_02_Base_F", "MBT_01_mlrs_base_F", "MBT_02_base_F", "APC_Wheeled_01_base_F", "AFV_Wheeled_01_base_F", "APC_Tracked_01_base_F", "MBT_04_base_F", "APC_Wheeled_02_base_F", "Heli_Transport_03_base_F", "CUP_T34_Base", "CUP_C47_Base", "CUP_AC47_Spooky_Base"];
VIOC_CA_SAFE2 = ["LSV_01_base_F", "Heli_Light_01_base_F", "SAM_System_01_base_F", "SAM_System_02_base_F", "SAM_System_03_base_F", "SAM_System_04_base_F", "Radar_System_01_base_F", "Radar_System_02_base_F", "MBT_03_base_F", "APC_Wheeled_03_base_F", "LT_01_base_F", "Truck_02_MRL_base_F"];
//--- B) bases compartidas: SOLO con el prefijo de VIOC_CA_PREFIX. Modo 2 agrega VIOC_CA_SHARED2.
VIOC_CA_SHARED1 = ["Heli_Transport_01_base_F", "Heli_Attack_01_base_F", "Heli_Attack_02_base_F", "Plane_CAS_02_base_F", "MBT_01_base_F", "APC_Tracked_02_base_F", "LSV_02_base_F", "Plane_CAS_01_base_F"];
VIOC_CA_SHARED2 = ["MRAP_01_base_F", "MRAP_02_base_F", "Truck_03_base_F", "Heli_Light_02_base_F", "UAV_02_base_F", "MRAP_03_base_F", "APC_Tracked_03_base_F", "Heli_light_03_base_F", "Heli_Transport_02_base_F", "Plane_Fighter_03_base_F", "Plane_Fighter_04_Base_F"];
VIOC_CA_PREFIX = ["b_", "o_", "i_", "c_", "ef_"];
//--- C) clases exactas (minusculas); tambien quedan cubiertas por sus bases CUP de la 2.a GM.
//    Mas el M60A3 (pedido del usuario): las 4 clases publicas de CUP de cfg.pkl (no hay M60A3 en RHS/GREF) y las 2 de CWr3
//    que nombran los archivos de la mision (CWr3 no esta en la linea de Tanoa).
VIOC_CA_EXACT = ["cup_i_t34_napa", "cup_i_t34_tk_gue", "cup_o_t34_tka", "cup_b_c47_usa", "cup_b_ac47_spooky_usa", "cup_o_c47_sla", "cup_b_m60a3_usmc", "cup_b_m60a3_tts_usmc", "cup_i_m60a3_racs", "cup_i_m60a3_tts_racs", "cwr3_b_m60a3", "cwr3_b_m60a3_tts"];
//--- M60A3 -> M1A1 Abrams (mismo nivel de mejora que tenia el M60A3); ver VIOC_CA_fnc_m1For
VIOC_CA_M60A3 = ["cup_b_m60a3_usmc", "cup_b_m60a3_tts_usmc", "cup_i_m60a3_racs", "cup_i_m60a3_tts_racs", "cwr3_b_m60a3", "cwr3_b_m60a3_tts"];
//--- lista blanca (minusculas): clases que nunca se quitan aunque caigan en una regla.
VIOC_CA_ALLOW = [];
//--- reemplazos en las guarniciones de pueblo (minusculas -> candidatos en orden; se usa el primero que exista y pase).
VIOC_CA_REPLACE = [
	["cup_i_t34_napa", ["CUP_I_T55_NAPA", "CUP_I_T72_NAPA"]],
	["cup_i_t34_tk_gue", ["CUP_I_T55_TK_GUE"]],
	["cup_o_t34_tka", ["CUP_O_T55_TK"]]
];
//--- reemplazos de defensas de la base por categoria, por bando (solo si la categoria se queda vacia).
VIOC_CA_DEF_REPLACE = [
	["WEST", "SAM", ["CUP_WV_B_RAM_Launcher"]],
	["EAST", "RADAR", ["rhs_p37_turret_vpvo"]]
];

VIOC_CA_SAFE = +VIOC_CA_SAFE1;
VIOC_CA_SHARED = +VIOC_CA_SHARED1;
if (VIOC_CA_MODE == 2) then {
	VIOC_CA_SAFE append VIOC_CA_SAFE2;
	VIOC_CA_SHARED append VIOC_CA_SHARED2;
};

//--- [clase] -> true si la politica la quita (con cache; en el modo 0 siempre false)
VIOC_CA_fnc_banned = {
	params [["_c", "", [""]]];
	if (VIOC_CA_MODE <= 0 || {_c == ""}) exitWith {false};
	private _lc = toLower _c;
	private _hit = VIOC_CA_CACHE get _lc;
	if (!isNil "_hit") exitWith {_hit};
	private _cfg = configFile >> "CfgVehicles" >> _c;
	private _r = false;
	if !(_lc in VIOC_CA_ALLOW) then {
		_r = (_lc in VIOC_CA_EXACT) || {isClass _cfg && {
			(({_c isKindOf _x} count VIOC_CA_SAFE) > 0)
			|| {(({(_lc find _x) == 0} count VIOC_CA_PREFIX) > 0) && {({_c isKindOf _x} count VIOC_CA_SHARED) > 0}}
			|| {(VIOC_CA_MODE in [1, 2]) && {!(_c isKindOf "Man")} && {((toLower configSourceMod _cfg) in ["ws", "rf", "ef"]) || {(toLower getText (_cfg >> "dlc")) in ["ws", "rf", "ef"]}}}
		}};
	};
	VIOC_CA_CACHE set [_lc, _r];
	_r
};

//--- [nombre de la lista] -> clase real (las unidades "custom" guardan su modelo en CTI_UNIT_SCRIPTS)
VIOC_CA_fnc_model = {
	params [["_v", "", [""]]];
	private _m = _v;
	private _rec = missionNamespace getVariable _v;
	if (!isNil "_rec" && {_rec isEqualType []} && {count _rec > CTI_UNIT_SCRIPTS}) then {
		private _s = _rec select CTI_UNIT_SCRIPTS;
		if (_s isEqualType [] && {count _s > 0} && {(_s select 0) isEqualType ""}) then {_m = _s select 0};
	};
	_m
};

//--- [bando] -> M1A1 que reemplaza al M60A3 en ese bando, o "" (solo si la nacion principal del bando es EE.UU.):
//    RHS principal -> rhsusf_m1a1aimwd_usarmy (desierto: rhsusf_m1a1aimd_usarmy); CUP principal -> M1A1SA de CUP en
//    woodland u oliva (desierto: M1A1SA desert); luego el del otro mod. Debe existir, ser publico (scope 2: el
//    "CUP_B_M1A1_Woodland_US_Army" es scope 1), no estar prohibido y estar registrado por la mision para este escenario
//    (tener datos de unidad: precio, nivel, fabrica); en Tanoa: pacifico -> CUP_B_M1A1SA_OD_US_Army, RHS -> rhsusf_m1a1aimwd_usarmy.
VIOC_CA_fnc_m1For = {
	params ["_side"];
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], []];
	if (count _mn < 2 || {!((_mn select 0) isEqualTo CTI_US_ID)}) exitWith {""};
	private _des = (missionNamespace getVariable ["CTI_CAMO_ACTIVATION", -1]) in [2, 7];
	private _cands = if ((_mn select 1) isEqualTo CTI_RHS_ID) then {
		if (_des) then {["rhsusf_m1a1aimd_usarmy", "CUP_B_M1A1SA_Desert_US_Army"]} else {["rhsusf_m1a1aimwd_usarmy", "CUP_B_M1A1SA_Woodland_US_Army", "CUP_B_M1A1SA_OD_US_Army"]}
	} else {
		if (_des) then {["CUP_B_M1A1SA_Desert_US_Army", "rhsusf_m1a1aimd_usarmy"]} else {["CUP_B_M1A1SA_Woodland_US_Army", "CUP_B_M1A1SA_OD_US_Army", "rhsusf_m1a1aimwd_usarmy"]}
	};
	private _ok = _cands select {isClass (configFile >> "CfgVehicles" >> _x) && {getNumber (configFile >> "CfgVehicles" >> _x >> "scope") >= 2} && {!([_x] call VIOC_CA_fnc_banned)} && {(missionNamespace getVariable [_x, 0]) isEqualType []}};
	if (count _ok == 0) exitWith {""};
	_ok select 0
};

//--- [clase quitada de un pueblo, bando] -> reemplazo contemporaneo verificado o ""
VIOC_CA_fnc_replacement = {
	params [["_c", "", [""]], ["_side", sideUnknown]];
	private _lc = toLower _c;
	if (_lc in VIOC_CA_M60A3) exitWith {
		private _m1 = [_side] call VIOC_CA_fnc_m1For;
		if (_m1 == "") then {VIOC_CA_MISSING pushBackUnique [_c, "sin M1 Abrams registrado para este bando: se quita sin reemplazo"]};
		_m1
	};
	private _i = VIOC_CA_REPLACE findIf {(_x select 0) == _lc};
	if (_i < 0) exitWith {""};
	private _ok = ((VIOC_CA_REPLACE select _i) select 1) select {isClass (configFile >> "CfgVehicles" >> _x) && {getNumber (configFile >> "CfgVehicles" >> _x >> "scope") >= 2} && {!([_x] call VIOC_CA_fnc_banned)}};
	if (count _ok == 0) exitWith {
		VIOC_CA_MISSING pushBackUnique [_c, "sin reemplazo contemporaneo cargado: se quita sin reemplazo"];
		""
	};
	_ok select 0
};

//--- Filtro: se llama una vez, desde Init_Common.sqf, justo antes de pylons.sqf
VIOC_CA_fnc_filterAll = {
	if (VIOC_CA_MODE <= 0) exitWith {diag_log "VIOC contemporary_assets: desactivado (VIOC_CONTEMPORARY_ASSETS = 0), no se quita nada"};
	private _fnc_note = {
		params ["_where", "_cls"];
		VIOC_CA_REMOVED pushBackUnique _cls;
		VIOC_CA_REMOVED_AT pushBack [_where, _cls];
	};

	//--- 0) M60A3 -> M1A1 en las fabricas: el M1 ocupa el lugar del M60A3 (si ya esta en la lista no se repite) y, si su
	//    nivel de mejora es mas alto que el del M60A3, baja a ese nivel (CTI_UNIT_UPGRADE en sus datos); su precio no cambia.
	{
		private _side = _x;
		private _m1 = [_side] call VIOC_CA_fnc_m1For;
		{
			private _var = format ["CTI_%1_%2Units", _side, _x];
			private _list = missionNamespace getVariable _var;
			if (!isNil "_list" && {_list isEqualType []} && {({_x isEqualType "" && {(toLower ([_x] call VIOC_CA_fnc_model)) in VIOC_CA_M60A3}} count _list) > 0}) then {
				private _new = [];
				{
					private _e = _x;
					if (_e isEqualType "" && {(toLower ([_e] call VIOC_CA_fnc_model)) in VIOC_CA_M60A3}) then {
						[_var, _e] call _fnc_note;
						if (_m1 == "") then {
							VIOC_CA_MISSING pushBackUnique [_var, format ["%1: sin M1 Abrams registrado para este bando, se quita sin reemplazo", _e]];
						} else {
							private _old = missionNamespace getVariable _e;
							private _rec = missionNamespace getVariable _m1;
							if (!isNil "_old" && {_old isEqualType []} && {count _old > CTI_UNIT_UPGRADE} && {(_old select CTI_UNIT_UPGRADE) isEqualType 0} && {(_rec select CTI_UNIT_UPGRADE) isEqualType 0} && {(_rec select CTI_UNIT_UPGRADE) > (_old select CTI_UNIT_UPGRADE)}) then {
								VIOC_CA_REPLACED pushBack [format ["%1 (nivel de mejora)", _m1], _rec select CTI_UNIT_UPGRADE, _old select CTI_UNIT_UPGRADE];
								_rec set [CTI_UNIT_UPGRADE, _old select CTI_UNIT_UPGRADE];
							};
							if ((_list findIf {_x isEqualType "" && {_x == _m1}}) < 0 && {(_new findIf {_x isEqualType "" && {_x == _m1}}) < 0}) then {_new pushBack _m1};
							VIOC_CA_REPLACED pushBack [_var, _e, _m1];
						};
					} else {
						_new pushBack _e;
					};
				} forEach _list;
				missionNamespace setVariable [_var, _new];
			};
		} forEach CTI_FACTORIES;
	} forEach [west, east, resistance];

	//--- 1) fabricas: menu de compra (jugador y comandante) y todo lo que lea CTI_<bando>_<fabrica>Units
	{
		private _side = _x;
		{
			private _var = format ["CTI_%1_%2Units", _side, _x];
			private _list = missionNamespace getVariable _var;
			if (!isNil "_list" && {_list isEqualType []}) then {
				private _keep = [];
				{
					if (_x isEqualType "" && {[[_x] call VIOC_CA_fnc_model] call VIOC_CA_fnc_banned}) then {[_var, _x] call _fnc_note} else {_keep pushBack _x};
				} forEach _list;
				if (count _keep != count _list) then {
					missionNamespace setVariable [_var, _keep];
					if (count _keep == 0) then {VIOC_CA_MISSING pushBack [_var, "la fabrica se queda sin unidades (no se pone ningun reemplazo)"]};
				};
			};
		} forEach CTI_FACTORIES;
	} forEach [west, east, resistance];

	//--- 2) escuadras de la IA (CTI_SQUAD_<bando>_<nombre>, elemento 2 = [[clase, cantidad, probabilidad], ...]).
	//    Una plantilla que se queda vacia se quita del todo (vacia colgaria Server_AI_PurchaseSquad.sqf).
	{
		private _side = _x;
		private _names = missionNamespace getVariable [format ["CTI_SQUADS_%1", _side], []];
		private _dropped = [];
		private _m1 = [_side] call VIOC_CA_fnc_m1For;
		{
			private _sname = _x;
			private _svar = format ["CTI_SQUAD_%1_%2", _side, _sname];
			private _sq = missionNamespace getVariable _svar;
			if (!isNil "_sq" && {_sq isEqualType []} && {count _sq > 2} && {(_sq select 2) isEqualType []}) then {
				private _pool = _sq select 2;
				private _keep = [];
				private _changed = false;
				{
					private _e = _x;
					private _cls = if (_e isEqualType [] && {count _e > 0}) then {_e select 0} else {_e};
					if (_cls isEqualType "" && {[[_cls] call VIOC_CA_fnc_model] call VIOC_CA_fnc_banned}) then {
						_changed = true;
						[_svar, _cls] call _fnc_note;
						//--- M60A3 -> el mismo M1A1 que en la fabrica, con la misma cantidad y probabilidad
						if ((toLower _cls) in VIOC_CA_M60A3 && {_m1 != ""}) then {
							private _ne = if (_e isEqualType []) then {+_e} else {[_e]};
							_ne set [0, _m1];
							_keep pushBack _ne;
							VIOC_CA_REPLACED pushBack [_svar, _cls, _m1];
						};
					} else {
						_keep pushBack _e;
					};
				} forEach _pool;
				if (_changed) then {
					if (count _keep == 0) then {
						_dropped pushBack _sname;
						missionNamespace setVariable [_svar, nil];
						VIOC_CA_MISSING pushBack [_svar, "plantilla de escuadra IA sin vehiculos contemporaneos: se quita"];
					} else {
						_sq set [2, _keep];
					};
				};
			};
		} forEach _names;
		if (count _dropped > 0) then {
			if (_names isEqualType []) then {missionNamespace setVariable [format ["CTI_SQUADS_%1", _side], _names - _dropped]};
			{
				private _lv = format ["CTI_SQUADS_%1_%2", _side, _x];
				private _l = missionNamespace getVariable _lv;
				if (!isNil "_l" && {_l isEqualType []}) then {missionNamespace setVariable [_lv, _l - _dropped]};
			} forEach ["Infantry", "Motorized", "AntiAir", "Armored", "Air", "KIND_INFANTRY", "KIND_LIGHT", "KIND_HEAVY", "KIND_AIR", "TOWN_DEFENSE"];
			{
				private _lv = format ["CTI_SQUADS_%1_CATEGORY_%2", _side, _x];
				private _l = missionNamespace getVariable _lv;
				if (!isNil "_l" && {_l isEqualType []}) then {
					private _k = _l select {!(_x isEqualType [] && {count _x > 0} && {(_x select 0) in _dropped})};
					if (count _k != count _l) then {
						if (count _k > 0) then {missionNamespace setVariable [_lv, _k]} else {
							missionNamespace setVariable [_lv, nil];
							VIOC_CA_MISSING pushBack [_lv, "categoria de escuadras IA sin plantillas: el comandante no asigna ese rol"];
						};
					};
				};
			} forEach ["INFANTRY", "LIGHT", "HEAVY", "AIR"];
		};
	} forEach [west, east, resistance];

	//--- 3) guarniciones de pueblo (<BANDO>_<tipo>; [clase, nivel] en Oeste/Este, [clase, 1] en la guerrilla).
	//    Vacia: la guerrilla usa infanteria (Server_SpawnTownResistance.sqf); Oeste/Este la quitan (Occupation la salta).
	{
		private _tag = _x;
		private _tside = [west, east, resistance] select (["WEST", "EAST", "GUER"] find _tag);
		{
			private _pv = format ["%1_%2", _tag, _x];
			private _p = missionNamespace getVariable _pv;
			if (!isNil "_p" && {_p isEqualType []} && {count _p > 0}) then {
				if ((_p select 0) isEqualType "") then {
					if ([_p select 0] call VIOC_CA_fnc_banned) then {
						private _old = _p select 0;
						[_pv, _old] call _fnc_note;
						private _rep = [_old, _tside] call VIOC_CA_fnc_replacement;
						if (_rep != "") then {
							_p set [0, _rep];
							VIOC_CA_REPLACED pushBack [_pv, _old, _rep];
						} else {
							if (_tag == "GUER") then {missionNamespace setVariable [_pv, []]} else {missionNamespace setVariable [_pv, nil]};
						};
					};
				} else {
					private _keep = [];
					private _changed = false;
					{
						private _e = _x;
						private _cls = if (_e isEqualType [] && {count _e > 0}) then {_e select 0} else {_e};
						if (_cls isEqualType "" && {[_cls] call VIOC_CA_fnc_banned}) then {
							_changed = true;
							[_pv, _cls] call _fnc_note;
							private _rep = [_cls, _tside] call VIOC_CA_fnc_replacement;
							if (_rep != "") then {
								private _ne = if (_e isEqualType []) then {+_e} else {[_e]};
								_ne set [0, _rep];
								_keep pushBack _ne;
								VIOC_CA_REPLACED pushBack [_pv, _cls, _rep];
							};
						} else {
							_keep pushBack _e;
						};
					} forEach _p;
					if (_changed) then {
						if (count _keep > 0 || {_tag == "GUER"}) then {missionNamespace setVariable [_pv, _keep]} else {missionNamespace setVariable [_pv, nil]};
					};
				};
			};
		} forEach ["WHEELED_SQ_LIGHT", "WHEELED_SQ_HEAVY", "TRACKED_SQ_LIGHT", "TRACKED_SQ_MEDIUM", "TRACKED_SQ_HEAVY", "AIR_SQ_FIGHTER", "AIR_SQ_BOMBER", "SQ_ANTI_AIR"];
	} forEach ["WEST", "EAST", "GUER"];

	//--- 4) vehiculos iniciales ([clase, equipo]); si no queda ninguno, el primer auto de nivel 0 de su fabrica ligera
	{
		private _side = _x;
		private _sv = format ["CTI_%1_Vehicles_Startup", _side];
		private _st = missionNamespace getVariable _sv;
		if (!isNil "_st" && {_st isEqualType []} && {count _st > 0}) then {
			private _keep = [];
			{
				if (_x isEqualType [] && {count _x > 0} && {(_x select 0) isEqualType ""} && {[_x select 0] call VIOC_CA_fnc_banned}) then {[_sv, _x select 0] call _fnc_note} else {_keep pushBack _x};
			} forEach _st;
			if (count _keep != count _st) then {
				if (count _keep == 0) then {
					private _alt = "";
					{
						private _rec = missionNamespace getVariable _x;
						if (_alt == "" && {_x isKindOf "Car"} && {([_x] call VIOC_CA_fnc_model) == _x} && {!isNil "_rec"} && {_rec isEqualType []} && {count _rec > CTI_UNIT_UPGRADE} && {(_rec select CTI_UNIT_UPGRADE) isEqualTo 0}) then {_alt = _x};
					} forEach (missionNamespace getVariable [format ["CTI_%1_%2Units", _side, CTI_LIGHT], []]);
					if (_alt != "") then {
						_keep = [[_alt, []]];
						VIOC_CA_REPLACED pushBack [_sv, "", _alt];
					} else {
						VIOC_CA_MISSING pushBack [_sv, "sin vehiculo inicial contemporaneo: el HQ empieza sin vehiculos"];
					};
				};
				missionNamespace setVariable [_sv, _keep];
			};
		};
	} forEach [west, east];

	//--- 5) defensas de la base (CTI_<bando>_DEFENSES: nombres "CTI_<bando>_<clase>" = [titulo, clase, precio, categoria,
	//    ubicacion, especial, nivel]) y la plantilla del comandante IA (CTI_<bando>_Defense_Template, de Base.sqf).
	//    Si una categoria se queda vacia: reemplazo contemporaneo del bando (VIOC_CA_DEF_REPLACE, mismo precio, ubicacion
	//    y nivel) o, si no lo hay, se quita la categoria del menu y de la plantilla del comandante (no construye nada ahi).
	{
		private _side = _x;
		private _sideStr = str _side;
		private _dv = format ["CTI_%1_DEFENSES", _side];
		private _defs = missionNamespace getVariable _dv;
		if (!isNil "_defs" && {_defs isEqualType []}) then {
			private _keep = [];
			private _lost = [];
			{
				private _rec = missionNamespace getVariable _x;
				if (!isNil "_rec" && {_rec isEqualType []} && {count _rec > 6} && {(_rec select 1) isEqualType ""} && {[_rec select 1] call VIOC_CA_fnc_banned}) then {
					[_dv, _rec select 1] call _fnc_note;
					_lost pushBack _rec;
				} else {
					_keep pushBack _x;
				};
			} forEach _defs;
			if (count _lost > 0) then {
				private _cats = [];
				{
					private _r = missionNamespace getVariable _x;
					if (!isNil "_r" && {_r isEqualType []} && {count _r > 3}) then {_cats pushBackUnique (_r select 3)};
				} forEach _keep;
				private _gone = [];
				{
					private _old = _x;
					private _cat = _old select 3;
					if !(_cat in _cats) then {
						private _rep = "";
						{
							if (_rep == "" && {(_x select 0) == _sideStr} && {(_x select 1) == _cat}) then {
								{
									if (_rep == "" && {isClass (configFile >> "CfgVehicles" >> _x)} && {getNumber (configFile >> "CfgVehicles" >> _x >> "scope") >= 2} && {!([_x] call VIOC_CA_fnc_banned)}) then {_rep = _x};
								} forEach (_x select 2);
							};
						} forEach VIOC_CA_DEF_REPLACE;
						if (_rep != "") then {
							private _nv = format ["CTI_%1_%2", _side, _rep];
							if (isNil {missionNamespace getVariable _nv}) then {
								private _lt = toLower _rep;
								private _mod = if ((_lt find "cup_") == 0) then {"[CUP] "} else {if ((_lt find "rhs") == 0) then {"[RHS] "} else {""}};
								missionNamespace setVariable [_nv, [_mod + getText (configFile >> "CfgVehicles" >> _rep >> "displayName"), _rep, _old select 2, _cat, _old select 4, _old select 5, _old select 6]];
							};
							_keep pushBackUnique _nv;
							_cats pushBackUnique _cat;
							VIOC_CA_REPLACED pushBack [_dv, _old select 1, _rep];
						} else {
							_gone pushBackUnique _cat;
						};
					};
				} forEach _lost;
				missionNamespace setVariable [_dv, _keep];
				if (count _gone > 0) then {
					private _cv = format ["CTI_%1_DEFENSECATEGORIES", _side];
					private _cl = missionNamespace getVariable _cv;
					if (!isNil "_cl" && {_cl isEqualType []}) then {missionNamespace setVariable [_cv, _cl - _gone]};
					private _tv = format ["CTI_%1_Defense_Template", _side];
					private _tl = missionNamespace getVariable _tv;
					if (!isNil "_tl" && {_tl isEqualType []}) then {
						missionNamespace setVariable [_tv, _tl select {!(_x isEqualType [] && {count _x > 1} && {(_x select 1) in _gone})}];
					};
					{
						VIOC_CA_MISSING pushBack [_dv, format ["sin %1 contemporaneo para %2: se quita del menu de defensas y de la plantilla del comandante IA", _x, _sideStr]];
					} forEach _gone;
				};
			};
		};
	} forEach [west, east];

	//--- 6) defensas de pueblo (solo existen en el servidor). Un tipo vacio se borra: la mision descarta los tipos sin
	//    definir (Server_SpawnTownDefense.sqf "learn and adapt"); vacio colgaria su bucle de eleccion.
	{
		private _tag = _x;
		{
			private _kv = format ["CTI_%1_Defenses_%2", _tag, _x];
			private _kl = missionNamespace getVariable _kv;
			if (!isNil "_kl" && {_kl isEqualType []}) then {
				private _keep = [];
				{
					if (_x isEqualType "" && {[_x] call VIOC_CA_fnc_banned}) then {[_kv, _x] call _fnc_note} else {_keep pushBack _x};
				} forEach _kl;
				if (count _keep != count _kl) then {
					if (count _keep > 0) then {missionNamespace setVariable [_kv, _keep]} else {
						missionNamespace setVariable [_kv, nil];
						VIOC_CA_MISSING pushBack [_kv, "tipo de defensa de pueblo sin estaticas contemporaneas: se quita"];
					};
				};
			};
		} forEach ["MG", "Mortar", "AA", "AT", "Artillery", "RADAR", "SAM"];
	} forEach ["WEST", "EAST", "GUER"];

	//--- 7) menu de artilleria
	private _art = missionNamespace getVariable ["CTI_ARTILLERY", []];
	if (_art isEqualType []) then {
		private _keep = [];
		{
			if (_x isEqualType "" && {[_x] call VIOC_CA_fnc_banned}) then {["CTI_ARTILLERY", _x] call _fnc_note} else {_keep pushBack _x};
		} forEach _art;
		if (count _keep != count _art) then {missionNamespace setVariable ["CTI_ARTILLERY", _keep]};
	};

	//--- registro (una vez por maquina, al empezar)
	private _byVar = [];
	{
		_x params ["_w", "_c"];
		private _i = _byVar findIf {(_x select 0) == _w};
		if (_i < 0) then {_byVar pushBack [_w, [_c]]} else {((_byVar select _i) select 1) pushBack _c};
	} forEach VIOC_CA_REMOVED_AT;
	diag_log format ["VIOC contemporary_assets: modo %1, %2 clases de vehiculo quitadas, %3 reemplazos, %4 avisos", VIOC_CA_MODE, count VIOC_CA_REMOVED, count VIOC_CA_REPLACED, count VIOC_CA_MISSING];
	{diag_log format ["VIOC contemporary_assets: quitado de %1: %2", _x select 0, _x select 1]} forEach _byVar;
	{diag_log format ["VIOC contemporary_assets: reemplazo en %1: %2 -> %3", _x select 0, _x select 1, _x select 2]} forEach VIOC_CA_REPLACED;
	{diag_log format ["VIOC contemporary_assets: FALTA en %1: %2", _x select 0, _x select 1]} forEach VIOC_CA_MISSING;
	if (hasInterface && {count VIOC_CA_MISSING > 0}) then {
		[] spawn {
			waitUntil {sleep 2; !isNull player && {time > 15}};
			systemChat format ["VIOC equipo contemporaneo: %1 opciones quitadas sin reemplazo contemporaneo (detalle en la consola: VIOC_CA_MISSING).", count VIOC_CA_MISSING];
		};
	};
	VIOC_CA_DONE = true;
};

//--- VIOC contemporary_assets: quita de fabricas, escuadras IA, pueblos, vehiculos iniciales, defensas y artilleria lo que no es contemporaneo (ver VIOC_contemporary.sqf)
if (isNil "VIOC_CA_fnc_filterAll") then {call compile preprocessFileLineNumbers "Common\Config\Units\VIOC_contemporary.sqf"};
call VIOC_CA_fnc_filterAll;

class VIOC_CONTEMPORARY_ASSETS {
	title = "VIOC: Solo vehiculos contemporaneos (sin 2a Guerra Mundial ni futuristas de 2035) en fabricas, escuadras IA, pueblos, defensas y partidas guardadas";
	values[] = {0,1,2,3};
	texts[] = {"No (todo como antes)","Si","Estricto (ademas Hunter, Ifrit, Prowler, Orca, MH-9, Tempest, drones, SAM/radar vanilla y AAF/LDF)","Si, pero conservar los vehiculos de WS/RF/EF que pasen las reglas"};
	default = 1;
};
